-- Isolated lifecycle scenario group; all assertions retained from the original suite.
begin;

select plan(42);

insert into auth.users (id, aud, role) values
  ('50000000-0000-0000-0000-000000000212', 'authenticated', 'authenticated'),
  ('50000000-0000-0000-0000-000000000213', 'authenticated', 'authenticated');

-- A buffered active renewal must get the same plan-specific admission handling
-- as direct delivery. It cannot create first admission: C's earlier active
-- start admits Early Access, then the folded live Standard renewal advances
-- the exact-plan marker. Later same-Standard lifecycle evidence stays valid
-- after Standard closes to new sales.
update public.plus_membership_plan set active = true where plan_code = 'plus_standard_monthly';
select is((select active from public.plus_membership_plan where plan_code='plus_standard_monthly'),true,'#164 buffered-plan transition enables Standard for the forward fixture');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-a','start-212-a','50000000-0000-0000-0000-000000000212','plus_early_access_monthly','membership_started',now() - interval '30 days',now() - interval '30 days',now() + interval '20 days'),'applied','#164 buffered-plan transition forward delivery starts A');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-c','renew-212-c-standard-buffered','50000000-0000-0000-0000-000000000212','plus_standard_monthly','membership_renewed',now() - interval '20 days',now() - interval '25 days',now() + interval '10 days'),'stale','#164 buffered-plan transition forward delivery retains the stale Standard renewal as C evidence');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-a','revoke-212-a','50000000-0000-0000-0000-000000000212','plus_early_access_monthly','membership_revoked',now() - interval '15 days',now() - interval '30 days',now() + interval '20 days'),'applied','#164 buffered-plan transition forward delivery retires A');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-c','start-212-c-early','50000000-0000-0000-0000-000000000212','plus_early_access_monthly','membership_started',now() - interval '25 days',now() - interval '25 days',now() + interval '5 days'),'applied','#164 buffered-plan transition forward delivery folds the Standard renewal after C is directly admitted');
select is((select plan_code from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000212'),'plus_standard_monthly','#164 buffered-plan transition forward delivery projects folded Standard state');
select is((select membership_status from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000212'),'active','#164 buffered-plan transition forward delivery projects folded active access');
select is((select admitted_plan_code from public.plus_membership_subscription where source_subscription_id='subscription-212-c'),'plus_standard_monthly','#164 buffered-plan transition forward delivery advances the exact-plan marker');
select is((select admitted_at from public.plus_membership_subscription where source_subscription_id='subscription-212-c'),(select occurred_at from public.plus_membership_event where source_system='source-a' and source_event_id='renew-212-c-standard-buffered'),'#164 buffered-plan transition forward delivery records folded renewal admission evidence');
update public.plus_membership_plan set active = false where plan_code = 'plus_standard_monthly';
select is((select active from public.plus_membership_plan where plan_code='plus_standard_monthly'),false,'#164 buffered-plan transition closes Standard after the admitted transition');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-c','renew-212-c-standard-closed','50000000-0000-0000-0000-000000000212','plus_standard_monthly','membership_renewed',now() - interval '15 days',now() - interval '15 days',now() + interval '12 days'),'applied','#164 buffered-plan transition accepts same-plan renewal after Standard closes');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-c','reactivate-212-c-standard-closed','50000000-0000-0000-0000-000000000212','plus_standard_monthly','membership_reactivated',now() - interval '14 days',now() - interval '14 days',now() + interval '13 days'),'applied','#164 buffered-plan transition accepts same-plan reactivation after Standard closes');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-c','restore-212-c-standard-closed','50000000-0000-0000-0000-000000000212','plus_standard_monthly','membership_restored',now() - interval '13 days',now() - interval '13 days',now() + interval '14 days'),'applied','#164 buffered-plan transition accepts same-plan restoration after Standard closes');
select is(public.record_plus_membership_event('source-a','customer-212','subscription-212-c','cancel-212-c-standard-closed','50000000-0000-0000-0000-000000000212','plus_standard_monthly','membership_canceled',now() - interval '12 days',now() - interval '13 days',now() + interval '14 days',true),'applied','#164 buffered-plan transition accepts same-plan period-end cancellation after Standard closes');
select is((select admitted_plan_code from public.plus_membership_subscription where source_subscription_id='subscription-212-c'),'plus_standard_monthly','#164 buffered-plan transition keeps the folded Standard marker after closed-plan lifecycle evidence');
select is((select admitted_at from public.plus_membership_subscription where source_subscription_id='subscription-212-c'),(select occurred_at from public.plus_membership_event where source_system='source-a' and source_event_id='renew-212-c-standard-buffered'),'#164 buffered-plan transition keeps the folded renewal admission evidence after closed-plan lifecycle evidence');
select is((select plan_code from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000212'),'plus_standard_monthly','#164 buffered-plan transition keeps Standard state after closed-plan lifecycle evidence');
select is((select membership_status from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000212'),'active','#164 buffered-plan transition keeps pre-cutoff active access after closed-plan lifecycle evidence');

-- Reverse delivery applies the same Standard renewal directly, then exercises
-- the same closed-plan lifecycle evidence for an exact convergence check.
update public.plus_membership_plan set active = true where plan_code = 'plus_standard_monthly';
select is((select active from public.plus_membership_plan where plan_code='plus_standard_monthly'),true,'#164 buffered-plan transition enables Standard for the reverse fixture');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-a','start-213-a','50000000-0000-0000-0000-000000000213','plus_early_access_monthly','membership_started',now() - interval '30 days',now() - interval '30 days',now() + interval '20 days'),'applied','#164 buffered-plan transition reverse delivery starts A');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-a','revoke-213-a','50000000-0000-0000-0000-000000000213','plus_early_access_monthly','membership_revoked',now() - interval '15 days',now() - interval '30 days',now() + interval '20 days'),'applied','#164 buffered-plan transition reverse delivery retires A');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-c','start-213-c-early','50000000-0000-0000-0000-000000000213','plus_early_access_monthly','membership_started',now() - interval '25 days',now() - interval '25 days',now() + interval '5 days'),'applied','#164 buffered-plan transition reverse delivery directly admits C on Early Access');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-c','renew-213-c-standard-direct','50000000-0000-0000-0000-000000000213','plus_standard_monthly','membership_renewed',now() - interval '20 days',now() - interval '25 days',now() + interval '10 days'),'applied','#164 buffered-plan transition reverse delivery applies the Standard renewal directly');
select is((select plan_code from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000213'),'plus_standard_monthly','#164 buffered-plan transition reverse delivery projects Standard state');
select is((select membership_status from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000213'),'active','#164 buffered-plan transition reverse delivery projects active access');
select is((select admitted_plan_code from public.plus_membership_subscription where source_subscription_id='subscription-213-c'),'plus_standard_monthly','#164 buffered-plan transition reverse delivery advances the exact-plan marker');
select is((select admitted_at from public.plus_membership_subscription where source_subscription_id='subscription-213-c'),(select occurred_at from public.plus_membership_event where source_system='source-a' and source_event_id='renew-213-c-standard-direct'),'#164 buffered-plan transition reverse delivery records direct renewal admission evidence');
update public.plus_membership_plan set active = false where plan_code = 'plus_standard_monthly';
select is((select active from public.plus_membership_plan where plan_code='plus_standard_monthly'),false,'#164 buffered-plan transition closes Standard after the direct transition');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-c','renew-213-c-standard-closed','50000000-0000-0000-0000-000000000213','plus_standard_monthly','membership_renewed',now() - interval '15 days',now() - interval '15 days',now() + interval '12 days'),'applied','#164 buffered-plan transition reverse accepts same-plan renewal after Standard closes');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-c','reactivate-213-c-standard-closed','50000000-0000-0000-0000-000000000213','plus_standard_monthly','membership_reactivated',now() - interval '14 days',now() - interval '14 days',now() + interval '13 days'),'applied','#164 buffered-plan transition reverse accepts same-plan reactivation after Standard closes');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-c','restore-213-c-standard-closed','50000000-0000-0000-0000-000000000213','plus_standard_monthly','membership_restored',now() - interval '13 days',now() - interval '13 days',now() + interval '14 days'),'applied','#164 buffered-plan transition reverse accepts same-plan restoration after Standard closes');
select is(public.record_plus_membership_event('source-a','customer-213','subscription-213-c','cancel-213-c-standard-closed','50000000-0000-0000-0000-000000000213','plus_standard_monthly','membership_canceled',now() - interval '12 days',now() - interval '13 days',now() + interval '14 days',true),'applied','#164 buffered-plan transition reverse accepts same-plan period-end cancellation after Standard closes');
select is((select admitted_plan_code from public.plus_membership_subscription where source_subscription_id='subscription-213-c'),'plus_standard_monthly','#164 buffered-plan transition reverse keeps the direct Standard marker after closed-plan lifecycle evidence');
select is((select admitted_at from public.plus_membership_subscription where source_subscription_id='subscription-213-c'),(select occurred_at from public.plus_membership_event where source_system='source-a' and source_event_id='renew-213-c-standard-direct'),'#164 buffered-plan transition reverse keeps direct renewal admission evidence after closed-plan lifecycle evidence');
select is((select plan_code from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000213'),'plus_standard_monthly','#164 buffered-plan transition reverse keeps Standard state after closed-plan lifecycle evidence');
select is((select membership_status from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000213'),'active','#164 buffered-plan transition reverse keeps pre-cutoff active access after closed-plan lifecycle evidence');
select is((select plan_code from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000212'),(select plan_code from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000213'),'#164 buffered-plan transition delivery orders converge on state');
select is((select membership_status from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000212'),(select membership_status from public.plus_membership_state where user_id='50000000-0000-0000-0000-000000000213'),'#164 buffered-plan transition delivery orders converge on state status');
select is((select membership_status from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000212'),(select membership_status from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000213'),'#164 buffered-plan transition delivery orders converge on access');
select is((select current_period_end from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000212'),(select current_period_end from public.plus_membership_access where user_id='50000000-0000-0000-0000-000000000213'),'#164 buffered-plan transition delivery orders converge on access horizon');
select is((select admitted_plan_code from public.plus_membership_subscription where source_subscription_id='subscription-212-c'),(select admitted_plan_code from public.plus_membership_subscription where source_subscription_id='subscription-213-c'),'#164 buffered-plan transition delivery orders converge on the exact admitted plan');
select is((select admitted_at from public.plus_membership_subscription where source_subscription_id='subscription-212-c'),(select admitted_at from public.plus_membership_subscription where source_subscription_id='subscription-213-c'),'#164 buffered-plan transition delivery orders converge on renewal admission evidence');

select * from finish();
rollback;
